'use client'

import { useCallback, useEffect, useMemo, useRef, useState, type ReactNode } from 'react'
import Link from 'next/link'
import { usePathname, useRouter } from 'next/navigation'
import { Activity, AlertTriangle, ArrowRight, Boxes, Check, CheckCircle2, ChevronRight, CircleHelp, ClipboardCheck, Clock3, Database, Download, FileText, Gauge, GitBranch, History, Home, Layers3, Menu, Network, Package, Play, RefreshCw, Search, ShieldCheck, Users, X } from 'lucide-react'
import { api } from '@/lib/api/client'
import type { IntegrationStatus, Overview } from '@/lib/api/contracts'
import { newId, runAgent, type AgentEvent } from '@/lib/agui/transport'
import { initialAgentState, reduceAgentState } from '@/lib/agui/state'
import type { AlternativePlan, AuditRecord, DecisionCertificate, DecisionOverride, DependencyGraph, DependencyNode, EvidenceRecord, ProposedDecision, Scenario, SimulationRequest, SimulationResult } from '@/types/domain'

const nav=[['Overview','/',Home],['Decision Workspace','/decisions',Layers3],['Decision Queue','/queue',ClipboardCheck],['Dependency Explorer','/dependencies',Network],['Decision History','/history',History],['Integration Center','/integrations',GitBranch]] as const
const tabs=['Proposed Decisions','Impact Analysis','Compare Alternatives','Approval'] as const
type Tab=typeof tabs[number]
const departments=['Inventory','Service','Rental','Sales','Finance']
const money=(minor:number|null|undefined)=>minor==null?'Unknown':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(minor/100)
const date=(value:string)=>new Date(value).toLocaleDateString('en-US',{month:'short',day:'numeric'})
const stamp=(value:string|null|undefined)=>value?new Date(value).toLocaleString():'Not yet'
const titleCase=(x:string)=>x.replaceAll('_',' ').replace(/^./,s=>s.toUpperCase())
const errorText=(x:unknown)=>x instanceof Error?x.message:String(x)
const initialPolicy:SimulationRequest['priorityPolicy']='protect_commitments'
const riskTone=(x:string)=>['critical','high','at risk','blocked','stale','error','failed'].includes(x)?'critical':['medium','warning','unknown','pending','not_tested'].includes(x)?'warning':['low','safe','protected','approved','connected','executed'].includes(x)?'success':'neutral'

function Badge({children,tone='neutral'}:{children:ReactNode;tone?:string}){return <span className={`badge ${tone}`}>{children}</span>}
function Btn({children,onClick,kind='secondary',disabled=false}:{children:ReactNode;onClick?:()=>void;kind?:string;disabled?:boolean}){return <button type="button" className={`btn ${kind}`} onClick={onClick} disabled={disabled}>{children}</button>}
function PageHeading({title,subtitle,action}:{title:string;subtitle:string;action?:ReactNode}){return <div className="page-heading"><div><div className="eyebrow">OPERATIONAL DECISION INTELLIGENCE</div><h1>{title}</h1><p>{subtitle}</p></div>{action}</div>}
function PanelTitle({title,subtitle,action}:{title:string;subtitle:string;action?:ReactNode}){return <div className="panel-title"><div><h2>{title}</h2><p>{subtitle}</p></div>{action}</div>}
function Kpi({icon,label,value,note,tone=''}:{icon:ReactNode;label:string;value:string;note:string;tone?:string}){return <div className="panel kpi-card"><div className={`kpi-icon ${tone}`}>{icon}</div><div><span>{label}</span><strong>{value}</strong><small>{note}</small></div></div>}
function Empty({text,action,onClick}:{text:string;action?:string;onClick?:()=>void}){return <div className="empty-state"><div className="empty-icon"><Layers3 size={20}/></div><b>{text}</b>{action&&<Btn kind="primary" onClick={onClick}>{action}</Btn>}</div>}
function Checklist({label,done}:{label:string;done:boolean}){return <div className="check-row"><span className={done?'check-done':'check-empty'}>{done?<Check size={12}/>:null}</span>{label}<Badge tone={done?'success':'neutral'}>{done?'Ready':'Pending'}</Badge></div>}
function download(filename:string,body:string,type:string){const href=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=href;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),1000)}
function toCSV(rows:(string|number|null|undefined)[][]){return rows.map(row=>row.map(x=>{let s=String(x??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}).join(',')).join('\r\n')}

type Inspection={title:string;subtitle:string;fields:[string,string][];evidenceIds?:string[]}
type ActivityItem={id:string;label:string;status:'running'|'completed'|'failed';detail?:string}
type RunSummary={id:string;lastEvent:string;events:number;status:string;elapsedMs?:number}

export default function ImpactIQApp(){
 const pathname=usePathname();const router=useRouter();const page=nav.find(n=>n[1]===pathname)?.[0]??'Overview'
 const [collapsed,setCollapsed]=useState(false),[inspector,setInspector]=useState(true),[mobileOpen,setMobileOpen]=useState(false)
 const [scenarios,setScenarios]=useState<Scenario[]>([]),[scenarioId,setScenarioId]=useState('SCN-002'),[overview,setOverview]=useState<Overview|null>(null),[history,setHistory]=useState<AuditRecord[]>([]),[integrations,setIntegrations]=useState<IntegrationStatus[]>([])
 const [tab,setTab]=useState<Tab>('Proposed Decisions'),[selected,setSelected]=useState<string[]>([]),[overrides,setOverrides]=useState<Record<string,DecisionOverride>>({}),[policy,setPolicy]=useState(initialPolicy),[maxCost,setMaxCost]=useState(''),[maxDelay,setMaxDelay]=useState(''),[protect,setProtect]=useState(true)
 const [simulation,setSimulation]=useState<SimulationResult|null>(null),[planId,setPlanId]=useState(''),[certificate,setCertificate]=useState<DecisionCertificate|null>(null),[note,setNote]=useState(''),[outdated,setOutdated]=useState(false)
 const [activity,setActivity]=useState<ActivityItem[]>([]),[run,setRun]=useState<RunSummary|null>(null),[analysisRunning,setAnalysisRunning]=useState(false),[loading,setLoading]=useState(true),[busy,setBusy]=useState(''),[error,setError]=useState(''),[toast,setToast]=useState('')
 const [query,setQuery]=useState(''),[department,setDepartment]=useState('All'),[statusFilter,setStatusFilter]=useState('All'),[originFilter,setOriginFilter]=useState('All'),[sort,setSort]=useState('Priority'),[historyDate,setHistoryDate]=useState(''),[queueIds,setQueueIds]=useState<string[]>([])
 const [inspection,setInspection]=useState<Inspection|null>(null),[graphFilter,setGraphFilter]=useState('All'),[selectedNode,setSelectedNode]=useState(''),[entityId,setEntityId]=useState(''),[explorer,setExplorer]=useState<{graph:DependencyGraph;evidence:EvidenceRecord[]}|null>(null),[exploring,setExploring]=useState(false)
 const [question,setQuestion]=useState(''),[explanation,setExplanation]=useState(''),[explaining,setExplaining]=useState(false),[commitmentFilter,setCommitmentFilter]=useState('All')
 const runAbort=useRef<AbortController|null>(null),explainAbort=useRef<AbortController|null>(null),scenarioRef=useRef('SCN-002'),mounted=useRef(false),writeLock=useRef(false),executionKey=useRef<Record<string,string>>({})
 const scenario=scenarios.find(s=>s.id===scenarioId)??null
 const decisions=scenario?.decisions??[]
 const allDecisions=useMemo(()=>scenarios.flatMap(s=>s.decisions),[scenarios])
 const chosen=simulation?.alternatives.find(p=>p.id===planId)??null
 const current=Boolean(simulation&&scenario&&simulation.sourceDataVersion===scenario.sourceDataVersion&&simulation.scenarioRevision===scenario.revision&&!outdated)
 const canApprove=Boolean(current&&simulation?.completeness==='complete'&&chosen?.feasible&&note.trim()&&!busy&&!analysisRunning)
 const canExecute=Boolean(certificate&&scenario&&current&&!certificate.stale&&certificate.sourceDataVersion===scenario.sourceDataVersion&&certificate.approvalStatus==='approved'&&certificate.executionStatus==='not_executed'&&certificate.selectedPlanId===planId&&!busy&&!analysisRunning)
 const sourceEvidence=page==='Dependency Explorer'?explorer?.evidence??[]:simulation?.evidence??[]
 const pending=decisions.filter(d=>d.status==='pending')

 const reportError=useCallback((e:unknown)=>{setError(errorText(e));setToast('')},[])
 const refreshOverview=useCallback(async()=>{const [o,h,i]=await Promise.all([api.overview(),api.history(),api.integrations()]);if(mounted.current){setOverview(o);setHistory(h.items);setIntegrations(i.items)}},[])
 const loadInitial=useCallback(async()=>{
  setLoading(true);setError('')
  try{const [ss,o,h,i]=await Promise.all([api.scenarios(),api.overview(),api.history(),api.integrations()]);if(!mounted.current)return;setScenarios(ss.items);setOverview(o);setHistory(h.items);setIntegrations(i.items);const s=ss.items.find(x=>x.id===scenarioRef.current)??ss.items[0];if(s){setScenarioId(s.id);scenarioRef.current=s.id;setSelected(s.decisions.filter(d=>d.status==='pending').map(d=>d.id))}}
  catch(e){if(mounted.current)reportError(e)}finally{if(mounted.current)setLoading(false)}
 },[reportError])
 useEffect(()=>{mounted.current=true;void loadInitial();return()=>{mounted.current=false;runAbort.current?.abort();explainAbort.current?.abort()}},[loadInitial])
 useEffect(()=>{setQuery('');setDepartment('All');setStatusFilter('All');setOriginFilter('All');setInspection(null);setMobileOpen(false)},[pathname])
 useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(''),5000);return()=>clearTimeout(timer)},[toast])
 useEffect(()=>{if(page!=='Dependency Explorer'||!scenario)return;let active=true;setExploring(true);setExplorer(null);const entity=entityId||scenario.resources[0]?.id||'';api.dependencies(scenario.id,entity).then(v=>{if(active)setExplorer(v)}).catch(e=>{if(active)reportError(e)}).finally(()=>{if(active)setExploring(false)});return()=>{active=false}},[page,scenario,entityId,reportError])

 function cancelRun(){runAbort.current?.abort();runAbort.current=null;setAnalysisRunning(false);setRun(old=>old?{...old,status:'Cancelled'}:old)}
 function invalidate(){cancelRun();explainAbort.current?.abort();setExplaining(false);setExplanation('');setOutdated(true);setCertificate(null);setPlanId('');setInspection(null);setSelectedNode('')}
 function chooseScenario(id:string,ids?:string[]){
  const next=scenarios.find(s=>s.id===id);if(!next)return;cancelRun();explainAbort.current?.abort();setExplaining(false);scenarioRef.current=id;setScenarioId(id);setSelected(ids??next.decisions.filter(d=>d.status==='pending').map(d=>d.id));setOverrides({});setPolicy(initialPolicy);setMaxCost('');setMaxDelay('');setProtect(true);setSimulation(null);setOutdated(false);setCertificate(null);setPlanId('');setNote('');setTab('Proposed Decisions');setActivity([]);setRun(null);setInspection(null);setEntityId('');setSelectedNode('');setExplorer(null);setExplanation('');setError('');
 }
 function openDecision(d:ProposedDecision){chooseScenario(d.scenarioId,d.status==='pending'?[d.id]:[]);router.push('/decisions')}
 function setSelection(ids:string[]){setSelected(ids);invalidate()}
 function update(id:string,patch:Partial<DecisionOverride>){setOverrides(old=>({...old,[id]:{...old[id],...patch,decisionId:id}}));invalidate()}
 function changeConstraints(change:()=>void){change();invalidate()}
 function restoreDraft(){if(!scenario)return;setSelection(pending.map(d=>d.id));setOverrides({});setPolicy(initialPolicy);setMaxCost('');setMaxDelay('');setProtect(true)}
 function replaceScenario(s:Scenario){setScenarios(old=>old.map(x=>x.id===s.id?s:x))}
 async function write<T>(label:string,operation:()=>Promise<T>):Promise<T|undefined>{if(writeLock.current)return;writeLock.current=true;setBusy(label);setError('');try{return await operation()}catch(e){reportError(e);return undefined}finally{writeLock.current=false;setBusy('')}}
 async function refresh(){await write('Refreshing',async()=>{
  const ss=await api.scenarios();if(!mounted.current)return;setScenarios(ss.items);const fresh=ss.items.find(s=>s.id===scenarioRef.current);if(fresh&&scenario&&fresh.sourceDataVersion!==scenario.sourceDataVersion){cancelRun();setOutdated(true);setSelected(old=>old.filter(id=>fresh.decisions.some(d=>d.id===id&&d.status==='pending')));if(certificate){const cert=await api.certificate(certificate.id);setCertificate(cert)}}await refreshOverview();setToast('Source snapshots refreshed.')
 })}
 async function resetScenario(){if(!scenario||analysisRunning)return;if(!window.confirm('Reset this fictional scenario? Current certificates will become stale. Audit records will be retained.'))return;await write('Resetting',async()=>{const fresh=await api.reset(scenario.id);replaceScenario(fresh);setSelected(fresh.decisions.map(d=>d.id));setOverrides({});setPolicy(initialPolicy);setMaxCost('');setMaxDelay('');setProtect(true);setSimulation(null);setCertificate(null);setPlanId('');setOutdated(false);setNote('');setActivity([]);setRun(null);setTab('Proposed Decisions');setInspection(null);setExplanation('');setSelectedNode('');await refreshOverview();setToast('Scenario reset. Audit history retained.')})}
 function makeRequest():SimulationRequest|null{if(!scenario||!selected.length)return null;const limit=(s:string,scale:number)=>s.trim()===''?undefined:Math.round(Number(s)*scale);return{scenarioId:scenario.id,scenarioRevision:scenario.revision,sourceDataVersion:scenario.sourceDataVersion,selectedDecisionIds:selected,overrides:selected.map(id=>overrides[id]).filter((o):o is DecisionOverride=>Boolean(o)),constraints:{protectCustomerCommitments:protect,currency:'USD',maxAdditionalCostMinor:limit(maxCost,100),maxDelayHours:limit(maxDelay,1)},priorityPolicy:policy}}
 async function analyze(){
  if(analysisRunning||busy)return;const request=makeRequest();if(!request){setError('Select at least one pending decision.');return}
  if(request.overrides.some(o=>o.quantity!==undefined&&(!Number.isInteger(o.quantity)||o.quantity<0||o.quantity>10000))||[maxCost,maxDelay].some(v=>v!==''&&(!Number.isFinite(Number(v))||Number(v)<0))){setError('Enter valid non-negative quantities and limits.');return}
  runAbort.current?.abort();explainAbort.current?.abort();setExplaining(false);setExplanation('');const controller=new AbortController();runAbort.current=controller;const runId=newId();let state=initialAgentState();const received:{result:SimulationResult|null}={result:null};let eventCount=0;let measured:number|undefined
  setAnalysisRunning(true);setError('');setToast('');setTab('Impact Analysis');setOutdated(false);setSimulation(null);setPlanId('');setCertificate(null);setActivity([]);setInspection(null);setSelectedNode('');setRun({id:runId,lastEvent:'Connecting',events:0,status:'Running'})
  const active=()=>mounted.current&&runAbort.current===controller&&!controller.signal.aborted&&scenarioRef.current===request.scenarioId
  const step=(id:string,label:string,status:ActivityItem['status'],detail?:string)=>setActivity(old=>{const existing=old.find(x=>x.id===id);return existing?old.map(x=>x.id===id?{...x,status,detail:detail??x.detail}:x):[...old,{id,label,status,detail}]})
  function event(e:AgentEvent){if(!active())return;eventCount++;setRun(old=>old?{...old,lastEvent:e.type,events:eventCount}:old)
   switch(e.type){
    case 'STATE_SNAPSHOT':case 'STATE_DELTA':state=reduceAgentState(state,e);if(state.simulation)received.result=state.simulation;break
    case 'TOOL_CALL_START':step(String(e.toolCallId),String(e.toolCallName).replace('retrieve_','Read ')+' MCP records','running');break
    case 'TOOL_CALL_RESULT':{let detail='MCP records retrieved';try{const data=JSON.parse(String(e.content));detail=`${data.records} records · ${data.latencyMs} ms · ${data.toolCalls.join(', ')}`}catch{}step(String(e.toolCallId),'MCP tool','completed',detail);break}
    case 'STEP_STARTED':step(String(e.stepName),String(e.stepName),'running');break
    case 'STEP_FINISHED':step(String(e.stepName),String(e.stepName),'completed');break
    case 'CUSTOM':if(e.name==='impactiq.metrics'){const v=e.value as {elapsedMs?:number};measured=v.elapsedMs}break
    case 'RUN_ERROR':setActivity(old=>old.map(a=>a.status==='running'?{...a,status:'failed'}:a));break
   }
  }
  try{await runAgent({threadId:request.scenarioId,runId,messages:[{id:newId(),role:'user',content:'Analyze the selected pending decisions.'}],state:{},tools:[],context:[],forwardedProps:{simulationRequest:request}},event,controller.signal);if(!active())return;if(!received.result)throw new Error('Analysis finished without a simulation result.');const completed=received.result;setSimulation(completed);setPlanId(completed.recommendedPlanId??completed.alternatives[0]?.id??'');setRun({id:runId,lastEvent:'RUN_FINISHED',events:eventCount,status:'Finished',elapsedMs:measured});setToast('Impact analysis completed using MCP source records.');void refreshOverview().catch(reportError)
  }catch(e){if(active()){setSimulation(null);setRun({id:runId,lastEvent:'RUN_ERROR',events:eventCount,status:'Failed'});setActivity(old=>old.map(a=>a.status==='running'?{...a,status:'failed'}:a));reportError(e)}}finally{if(runAbort.current===controller){runAbort.current=null;setAnalysisRunning(false)}}
 }
 async function review(action:'approve'|'reject'){
  if(!simulation||!scenario||!chosen||!current||!note.trim()||(action==='approve'&&!canApprove))return
  await write(action==='approve'?'Approving':'Rejecting',async()=>{const cert=await api.approve({scenarioId:scenario.id,simulationId:simulation.id,selectedPlanId:chosen.id,scenarioRevision:simulation.scenarioRevision,sourceDataVersion:simulation.sourceDataVersion,action,note:note.trim()});setCertificate(cert);await refreshOverview();setToast(action==='approve'?'Approved. Sandbox execution is still separate.':'Rejection recorded in audit history.')})
 }
 async function mutate(){if(!scenario)return;await write('Changing source',async()=>{const s=await api.mutate(scenario.id);replaceScenario(s);setOutdated(true);if(certificate)setCertificate(await api.certificate(certificate.id));await refreshOverview();setToast('Source data changed. Previous approval cannot execute.')})}
 async function execute(){if(!canExecute||!certificate)return;const certId=certificate.id;executionKey.current[certId]??=newId();await write('Executing',async()=>{const output=await api.execute(certId,executionKey.current[certId]);setCertificate(output.certificate);replaceScenario(output.scenario);setSelected(output.scenario.decisions.filter(d=>d.status==='pending').map(d=>d.id));setOutdated(true);await refreshOverview();setToast('Approved allocations committed to the fictional SQLite sandbox.')})}
 async function viewCertificate(id:string){await write('Loading certificate',async()=>{const c=await api.certificate(id);setInspector(true);setInspection({title:c.id,subtitle:'Decision certificate · '+c.approvalStatus,fields:Object.entries(c).map(([k,v])=>[k,typeof v==='object'?JSON.stringify(v):String(v)])})})}
 async function testConnector(id:string){await write('Testing connector',async()=>{const value=await api.testConnector(id);setIntegrations(old=>old.map(x=>x.id===id?value:x));setToast(`${value.name}: real MCP handshake and tool call succeeded.`)})}
 async function ask(text:string){if(!simulation||explaining||!current)return;explainAbort.current?.abort();const controller=new AbortController();explainAbort.current=controller;setExplaining(true);setExplanation('');setError('');let buffer='';const runId=newId();try{await runAgent({threadId:simulation.scenarioId,runId,messages:[{id:newId(),role:'user',content:text}],state:{},tools:[],context:[],forwardedProps:{operation:'explain',simulationId:simulation.id,question:text}},e=>{if(explainAbort.current!==controller)return;if(e.type==='TEXT_MESSAGE_CONTENT'){buffer+=String(e.delta??'');setExplanation(buffer)}},controller.signal)}catch(e){if(!controller.signal.aborted)reportError(e)}finally{if(explainAbort.current===controller){explainAbort.current=null;setExplaining(false)}}}
 function inspectEvidence(e:EvidenceRecord){setInspector(true);setInspection({title:e.recordType,subtitle:`${e.sourceSystem} · ${e.recordId}`,fields:[['Retrieval',e.retrievalStatus],['Source version',e.sourceDataVersion],['Retrieved',stamp(e.retrievedAt)],...Object.entries(e.relevantFields).map(([k,v]):[string,string]=>[k,String(v)])]})}
 function inspectNode(n:DependencyNode){setInspector(true);setSelectedNode(n.id);setInspection({title:n.label,subtitle:n.category,fields:[['Entity',n.entityId],['Department',n.department],['Risk',n.severity],['Relationship',n.description]],evidenceIds:n.evidenceIds})}
 const filteredQueue=allDecisions.filter(d=>(department==='All'||d.department===department)&&(originFilter==='All'||d.origin===originFilter)&&(statusFilter==='All'||d.status===statusFilter)&&`${d.id} ${d.title} ${d.resourceId} ${d.proposedBy}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>sort==='Deadline'?a.requiredAt.localeCompare(b.requiredAt):['critical','high','normal'].indexOf(a.priority)-['critical','high','normal'].indexOf(b.priority))
 const filteredHistory=history.filter(h=>(statusFilter==='All'||h.eventType===statusFilter)&&(!historyDate||h.timestamp.slice(0,10)===historyDate)&&`${h.id} ${h.eventType} ${h.description} ${h.scenarioId} ${h.certificateId??''}`.toLowerCase().includes(query.toLowerCase()))
 function openQueue(){const ds=allDecisions.filter(d=>queueIds.includes(d.id)&&d.status==='pending');if(!ds.length){setError('Select pending decisions to analyze.');return}if(new Set(ds.map(d=>d.scenarioId)).size!==1){setError('Choose decisions from one supported scenario. Independent demo scenarios cannot be combined.');return}chooseScenario(ds[0].scenarioId,ds.map(d=>d.id));router.push('/decisions')}
 const csvExport=()=>download('impactiq-history.csv',toCSV([['Event ID','Scenario','Event','User','Description','Source version','Before exposure (USD)','After exposure (USD)','Timestamp','Certificate'],...filteredHistory.map(h=>[h.id,h.scenarioId,h.eventType,h.user,h.description,String(h.metadata.sourceDataVersion??''),typeof h.metadata.exposureBeforeMinor==='number'?h.metadata.exposureBeforeMinor/100:'',typeof h.metadata.exposureAfterMinor==='number'?h.metadata.exposureAfterMinor/100:'',h.timestamp,h.certificateId])]),'text/csv;charset=utf-8')
 const activeGraph=page==='Dependency Explorer'?explorer?.graph:simulation?.graph
 const isWorking=Boolean(busy||analysisRunning)

 return <div className="app-shell">
  <aside className={`sidebar ${collapsed?'collapsed':''} ${mobileOpen?'mobile-open':''}`}>
   <div className="brand-row"><div className="brand"><span className="brandmark"><i/><i/><i/><i/></span><span className="brandtext">Impact<span>IQ</span><small>DECISION INTELLIGENCE</small></span></div><button className="collapse" aria-label={collapsed?'Expand navigation':'Collapse navigation'} onClick={()=>setCollapsed(v=>!v)}><Menu size={16}/></button></div>
   <div className="side-context"><i className="context-dot"/>DEMO ENVIRONMENT</div><div className="side-label">WORKSPACE</div>
   <nav>{nav.map(([label,href,Icon])=><Link key={href} href={href} title={label} aria-current={pathname===href?'page':undefined} className={`nav-item ${page===label?'active':''}`}><Icon size={17}/><span>{label}</span>{label==='Decision Queue'&&overview&&<b>{overview.metrics.pending}</b>}</Link>)}</nav>
   <div className="sidebar-bottom"><div className="branchbox"><span>ACTIVE DEALERSHIP</span><strong>Meridian Equipment</strong><small>All branches · fictional data</small></div><div className="user-card"><span className="avatar">AM</span><span><b>Alex Morgan</b><small>Operations Manager · demo</small></span></div><button className="reset-side" disabled={!scenario||isWorking} onClick={()=>void resetScenario()}><RefreshCw size={13}/> Reset current scenario</button></div>
  </aside>
  <section className="main-shell"><header className="topbar"><div className="crumb"><button className="mobile-menu" onClick={()=>setMobileOpen(v=>!v)} aria-label="Toggle navigation"><Menu size={17}/></button><span>Meridian Equipment Group</span><ChevronRight size={14}/><b>{page}</b></div><div className="top-actions"><span className="fresh"><i/>Fictional source data</span><span className="mode"><i/>{loading?'Connecting':scenarios.length?'Local API':'Disconnected'}</span><button className="icon-btn" aria-label="Refresh data" disabled={isWorking||loading} onClick={()=>void refresh()}><RefreshCw size={15}/></button><button className="icon-btn" aria-label="About ImpactIQ" onClick={()=>setToast('Proposed VitalEdge product extension. All data and transaction execution are confined to this local demo sandbox.')}><CircleHelp size={16}/></button></div></header>
  <div className="content-area"><main className={`main-content ${!inspector?'wide-content':''}`}>
   {error&&<div className="notice error-notice" role="alert"><AlertTriangle size={17}/><span><b>{error}</b><small>Review the input or refresh the source data before trying again.</small></span><button className="icon-btn" aria-label="Dismiss error" onClick={()=>setError('')}><X size={15}/></button></div>}
   {loading?<Empty text="Connecting to the ImpactIQ backend…"/>:!scenario?<Empty text="Local API unavailable. Start FastAPI on port 8000, then reconnect." action="Reconnect" onClick={()=>void loadInitial()}/>:<>
   {page==='Overview'&&<>
    <PageHeading title="Decision Intelligence Overview" subtitle="Evaluate operational decisions before they affect your business." action={<Link className="btn primary" href="/decisions"><Layers3 size={15}/> Open Decision Workspace <ArrowRight size={15}/></Link>}/>
    <div className="kpi-grid"><Kpi icon={<ClipboardCheck/>} label="Pending decisions" value={String(overview?.metrics.pending??'—')} note="Across three independent scenarios"/><Kpi icon={<AlertTriangle/>} label="Resource conflicts" value={String(overview?.metrics.conflicts??'—')} note="Modeled constraint violations" tone="warning"/><Kpi icon={<Users/>} label="Commitments at risk" value={String(overview?.metrics.commitments??'—')} note="From current source records" tone="critical"/><Kpi icon={<Gauge/>} label="Revenue exposure" value={money(overview?.metrics.exposure)} note="Estimate, not a confirmed loss" tone="teal"/></div>
    <div className="overview-grid"><section className="panel"><PanelTitle title="Pending decisions" subtitle="Employee and AI-agent proposals" action={<Link href="/queue" className="text-link">View queue <ArrowRight size={14}/></Link>}/><div className="table-wrap"><table><thead><tr><th>DECISION</th><th>PROPOSED ACTION</th><th>DEPARTMENT</th><th>ORIGIN</th><th>PRIORITY</th><th/></tr></thead><tbody>{allDecisions.filter(d=>d.status==='pending').map(d=><tr key={d.id}><td><b>{d.id}</b></td><td className="action-cell"><b>{d.title}</b><small>{d.resourceId} · {d.sourceBranchId}</small></td><td>{d.department}</td><td><Badge tone={d.origin==='AI Agent'?'info':'neutral'}>{d.origin}</Badge></td><td><Badge tone={riskTone(d.priority)}>{titleCase(d.priority)}</Badge></td><td><button className="table-link" onClick={()=>openDecision(d)}>Review <ArrowRight size={13}/></button></td></tr>)}</tbody></table>{!allDecisions.some(d=>d.status==='pending')&&<Empty text="All proposals committed. Reset a scenario to demonstrate again."/>}</div></section><section className="panel dept-panel"><PanelTitle title="Department workload" subtitle="Pending decisions by originating department"/>{departments.map(d=>{const n=allDecisions.filter(x=>x.department===d&&x.status==='pending').length;return <div className="dept-stat" key={d}><span>{d}</span><div className="stock-track"><i style={{width:`${n/Math.max(1,allDecisions.length)*100}%`}}/></div><b>{n}</b></div>})}<p className="impact-cost-foot">Analysis is scoped to supported scenarios; totals are illustrative.</p></section></div>
    <div className="bottom-grid"><section className="panel showcase"><div className="showcase-icon"><Network size={19}/></div><div><Badge tone="info">PRIMARY DEMONSTRATION</Badge><h2>Individually feasible. Collectively conflicting.</h2><p>Evaluate several departmental proposals together against shared inventory and customer deadlines.</p><div className="showcase-meta"><span><Package size={14}/> Hydraulic Pump HP-220</span><span><Clock3 size={14}/> Version-bound simulation</span></div></div><Btn onClick={()=>{chooseScenario('SCN-002');router.push('/decisions')}}>Review scenario <ArrowRight size={14}/></Btn></section><section className="panel activity-panel"><PanelTitle title="Recent activity" subtitle="Actual sandbox audit events" action={<Link href="/history" className="text-link">History</Link>}/>{history.length?history.slice(0,4).map(h=><div className="activity-item" key={h.id}><span className="activity-marker teal"><CheckCircle2 size={14}/></span><div><b>{titleCase(h.eventType)}</b><small>{h.scenarioId} · {stamp(h.timestamp)}</small></div></div>):<Empty text="No activity yet. Run a simulation to begin."/>}</section></div>
   </>}
   {page==='Decision Workspace'&&<>
    <PageHeading title="Decision Workspace" subtitle={scenario.description} action={<div className="heading-actions"><Btn disabled={isWorking} onClick={()=>void resetScenario()}><RefreshCw size={14}/> Reset Scenario</Btn><Btn kind="primary" disabled={!selected.length||isWorking} onClick={()=>void analyze()}><Play size={14}/> Analyze Impact</Btn>{analysisRunning&&<Btn onClick={cancelRun}>Cancel</Btn>}</div>}/>
    <div className="workspace-controls"><label className="scenario-select">Scenario <select aria-label="Select scenario" value={scenarioId} disabled={Boolean(busy)} onChange={e=>chooseScenario(e.target.value)}>{scenarios.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label><span className="version-label">Revision {scenario.revision} · {scenario.sourceDataVersion}</span><Badge tone={certificate?.executionStatus==='executed'?'success':outdated?'warning':analysisRunning?'info':simulation?riskTone(simulation.status):'neutral'}>{certificate?.executionStatus==='executed'?'Executed':outdated?'Outdated':analysisRunning?'Analyzing':simulation?titleCase(simulation.status):'Draft'}</Badge><span className="last-analysis">{simulation?`Analyzed ${stamp(simulation.generatedAt)}`:'Not yet analyzed'}</span></div>
    <div className="tabs" role="tablist">{tabs.map((x,i)=><button key={x} role="tab" aria-selected={tab===x} className={tab===x?'selected':''} onClick={()=>setTab(x)}><span className="tab-num">0{i+1}</span>{x}{x==='Approval'&&certificate&&<Check size={13}/>}</button>)}</div>
    {outdated&&<div className="notice warning-notice"><AlertTriangle size={17}/><span><b>Previous analysis is not current.</b> Draft inputs or business records changed. Reanalyze before approving or executing.</span></div>}
    {tab==='Proposed Decisions'&&<>
      <section className="panel table-panel"><PanelTitle title={`Proposed decisions · ${selected.length} selected`} subtitle="Simulation drafts never change confirmed business records." action={<button disabled={isWorking} className="text-link" onClick={restoreDraft}>Restore defaults</button>}/><div className="table-wrap"><table className="decision-table"><thead><tr><th><input type="checkbox" aria-label="Select all pending decisions" checked={pending.length>0&&pending.every(d=>selected.includes(d.id))} disabled={isWorking||!pending.length} onChange={e=>setSelection(e.target.checked?pending.map(d=>d.id):[])}/></th><th>DECISION</th><th>DEPARTMENT / ORIGIN</th><th>PROPOSED BY</th><th>ACTION / RESOURCE</th><th>QTY</th><th>REQUIRED BY</th><th>INDIVIDUAL</th></tr></thead><tbody>{decisions.map(d=>{const o=overrides[d.id];const evaluation=current?simulation?.individualEvaluations.find(x=>x.decisionId===d.id):null;const branch=o?.sourceBranchId??d.sourceBranchId;const stock=scenario.resources.find(r=>r.branchId===branch&&r.resourceType==='part');const estimate=stock?(o?.quantity??d.quantity??0)<=Math.max(0,(stock.availableQuantity??0)-stock.committedQuantity):null;return <tr key={d.id}><td><input aria-label={`Include ${d.id}`} type="checkbox" checked={selected.includes(d.id)} disabled={isWorking||d.status!=='pending'} onChange={e=>setSelection(e.target.checked?[...selected,d.id]:selected.filter(x=>x!==d.id))}/></td><td><b>{d.id}</b><small>{d.status}</small></td><td>{d.department}<small>{d.origin}</small></td><td>{d.proposedBy}</td><td><b>{d.title}</b><small>{d.resourceId} · {branch}</small></td><td>{scenario.id==='SCN-003'?d.quantity:<input className="qty-input" type="number" min="0" max="10000" step="1" aria-label={`${d.id} quantity`} disabled={isWorking||d.status!=='pending'} value={o?.quantity??d.quantity??1} onChange={e=>update(d.id,{quantity:Number(e.target.value)})}/>}</td><td>{date(o?.requiredAt??d.requiredAt)}</td><td><Badge tone={evaluation?evaluation.feasible?'success':'critical':estimate===null?'neutral':estimate?'success':'warning'}>{evaluation?evaluation.feasible?'Feasible':'Conflict':estimate===null?'Not evaluated':estimate?'Fits stock*':'Exceeds stock*'}</Badge></td></tr>})}</tbody></table></div></section>
      <div className="notice info-notice"><ShieldCheck size={16}/><span><b>Preflight only.</b> *Local stock estimates are not server validation. Analyze the combined set to verify constraints.</span></div>
      <section className="panel"><PanelTitle title="Source inventory and commitments" subtitle="Read-only fictional ERP snapshot"/><div className="table-wrap"><table><thead><tr><th>RESOURCE</th><th>BRANCH</th><th>PHYSICAL</th><th>RESERVED</th><th>UNALLOCATED</th><th>VERSION</th></tr></thead><tbody>{scenario.resources.map(r=><tr key={r.id}><td><b>{r.name}</b><small>{r.id}</small></td><td>{r.branchId}</td><td>{r.availableQuantity??'Unknown'}</td><td>{r.committedQuantity}</td><td>{r.availableQuantity==null?'Unknown':Math.max(0,r.availableQuantity-r.committedQuantity)}</td><td>{r.version}</td></tr>)}</tbody></table></div></section>
      {scenario.id==='SCN-003'&&<section className="panel"><PanelTitle title="Asset scheduling timeline" subtitle="Fixed, half-open demo intervals. Exact handover boundaries do not overlap."/><div className="timeline-list">{decisions.map(d=><div key={d.id} className="timeline-item"><b>{d.department}</b><span>{d.title}</span><small>{stamp(d.startAt)} → {stamp(d.endAt)}</small></div>)}</div></section>}
    </>}
    {tab==='Impact Analysis'&&<>
     {analysisRunning?<section className="panel analysis-loading"><div className="loading-head"><span className="empty-icon"><Activity size={17}/></span><div><b>Analyzing proposed decisions</b><small>Waiting for actual MCP tool responses.</small></div></div><ActivityList items={activity}/><Btn onClick={cancelRun}>Cancel run</Btn></section>:simulation?<ImpactPanel result={simulation} scenario={scenario} current={current} commitmentFilter={commitmentFilter} onCommitmentFilter={setCommitmentFilter} graphFilter={graphFilter} setGraphFilter={setGraphFilter} selectedNode={selectedNode} onNode={inspectNode} onEvidence={inspectEvidence} onAlternatives={()=>setTab('Compare Alternatives')}/>:<Empty text="No simulation result yet." action="Analyze impact" onClick={()=>void analyze()}/>}
    </>}
    {tab==='Compare Alternatives'&&<>
      <section className="panel alternatives-panel"><PanelTitle title="Compare operational plans" subtitle="All plans use one source snapshot and the same business constraints." action={<Btn disabled={isWorking||!selected.length} onClick={()=>void analyze()}><RefreshCw size={14}/> Recalculate</Btn>}/>{simulation?<><div className="alternative-grid">{simulation.alternatives.map(p=><PlanCard key={p.id} plan={p} selected={p.id===planId} recommended={p.id===simulation.recommendedPlanId} count={scenario.commitments.length} disabled={!current||isWorking} onSelect={()=>{setPlanId(p.id);setCertificate(null);setNote('')}}/>)}</div>{!simulation.recommendedPlanId&&<div className="notice warning-notice"><AlertTriangle size={15}/> No plan satisfies all current constraints. Change the draft or escalate manually.</div>}</>:<Empty text="Run an analysis to compare plans." action="Analyze impact" onClick={()=>void analyze()}/>}
      <div className="whatif"><div><h3>What-if controls</h3><p>Edit supported inputs, then explicitly recalculate. No network call is made while typing.</p></div><div className="whatif-controls editable-controls">{pending.filter(d=>selected.includes(d.id)&&d.actionType==='transfer').map(d=><div className="control-group" key={d.id}><label>{d.id} quantity<input type="number" min="0" step="1" max="10000" value={overrides[d.id]?.quantity??d.quantity??0} disabled={isWorking} onChange={e=>update(d.id,{quantity:Number(e.target.value)})}/></label><label>Source branch<select value={overrides[d.id]?.sourceBranchId??d.sourceBranchId} disabled={isWorking} onChange={e=>update(d.id,{sourceBranchId:e.target.value})}>{scenario.resources.filter(r=>r.resourceType==='part'&&r.branchId!==d.targetBranchId).map(r=><option key={r.id}>{r.branchId}</option>)}</select></label></div>)}<label>Max additional cost ($)<input type="number" min="0" step="1" placeholder="No limit" value={maxCost} disabled={isWorking} onChange={e=>changeConstraints(()=>setMaxCost(e.target.value))}/></label><label>Max delay (hours)<input type="number" min="0" step="1" placeholder="No limit" value={maxDelay} disabled={isWorking} onChange={e=>changeConstraints(()=>setMaxDelay(e.target.value))}/></label><label>Priority policy<select value={policy} disabled={isWorking} onChange={e=>changeConstraints(()=>setPolicy(e.target.value as SimulationRequest['priorityPolicy']))}><option value="protect_commitments">Protect commitments</option><option value="minimize_cost">Minimize cost</option><option value="minimize_delay">Minimize delay</option></select></label><label className="check-control"><input type="checkbox" checked={protect} disabled={isWorking} onChange={e=>changeConstraints(()=>setProtect(e.target.checked))}/> Protect customer promises</label></div><div className="edit-deadlines">{pending.filter(d=>selected.includes(d.id)&&scenario.id!=='SCN-003').map(d=><div className="control-group" key={d.id}><label>{d.id} deadline (UTC)<input type="datetime-local" value={(overrides[d.id]?.requiredAt??d.requiredAt).slice(0,16)} disabled={isWorking} onChange={e=>{if(e.target.value)update(d.id,{requiredAt:e.target.value+':00Z'})}}/></label><label>Priority<select value={overrides[d.id]?.priority??d.priority} disabled={isWorking} onChange={e=>update(d.id,{priority:e.target.value as ProposedDecision['priority']})}><option value="normal">Normal</option><option value="high">High</option><option value="critical">Critical</option></select></label></div>)}</div><div className="decision-footer"><Btn disabled={isWorking||!selected.length} onClick={()=>void analyze()}>Recalculate</Btn><Btn kind="primary" disabled={!current||!chosen?.feasible||isWorking} onClick={()=>setTab('Approval')}>Review selected plan <ArrowRight size={14}/></Btn></div></div></section>
    </>}
    {tab==='Approval'&&<div className="approval-layout"><section className="panel approval-panel"><PanelTitle title="Human approval" subtitle="Approval and execution are separate, server-validated transactions."/>{simulation&&chosen?<><div className="approval-summary"><div><small>SELECTED PLAN</small><b>{chosen.title}</b></div><div><small>SIMULATION</small><b>{simulation.id}</b></div><div><small>EXPOSURE BEFORE</small><b>{money(simulation.impactSummary.revenueAtRiskMinor)}</b></div><div><small>EXPOSURE AFTER</small><b>{money(chosen.impactSummary.revenueAtRiskMinor)}</b></div></div><div className="approval-risk"><ShieldCheck size={18}/><div><b>{chosen.feasible?'Modeled constraints satisfied':'Plan violates constraints'}</b><p>{chosen.recommendationReason} · {chosen.impactSummary.protectedCommitments} protected commitment(s).</p></div></div><label className="note-label" htmlFor="approval-note">Review note · required</label><textarea id="approval-note" maxLength={2000} value={note} disabled={Boolean(busy)} onChange={e=>setNote(e.target.value)} placeholder="Document rationale and conditions…"/><div className="approval-actions"><Btn disabled={!current||!note.trim()||isWorking} onClick={()=>void review('reject')}>Reject plan</Btn><Btn kind="primary" disabled={!canApprove} onClick={()=>void review('approve')}><ShieldCheck size={14}/> Approve plan</Btn></div></>:!certificate?<Empty text="Analyze and select a plan before approval." action="Go to analysis" onClick={()=>setTab('Impact Analysis')}/>:null}
     {certificate&&<div className={`certificate ${certificate.stale?'stale':''}`}><div className="certificate-head"><div><Badge tone={certificate.stale?'critical':riskTone(certificate.executionStatus==='executed'?'executed':certificate.approvalStatus)}>{certificate.stale?'STALE':certificate.executionStatus==='executed'?'EXECUTED':titleCase(certificate.approvalStatus)}</Badge><h3>{certificate.id}</h3><small>{certificate.sourceDataVersion}</small></div><div className="heading-actions"><Btn onClick={()=>download(`${certificate.id}.json`,JSON.stringify(certificate,null,2),'application/json')}><Download size={13}/> JSON</Btn><Btn onClick={()=>window.print()}>Print</Btn></div></div><p>{certificate.planTitle??certificate.selectedPlanId} · {certificate.approver} · {stamp(certificate.approvedAt)}</p><p>{certificate.approvalNote}</p><p>Execution: {titleCase(certificate.executionStatus)} {certificate.executedAt?`· ${stamp(certificate.executedAt)}`:''}</p><div className="execute-row"><Btn disabled={isWorking||certificate.executionStatus==='executed'} onClick={()=>void mutate()}><Database size={14}/> Simulate Source Data Change</Btn><Btn kind="primary" disabled={!canExecute} onClick={()=>void execute()}><Play size={13}/> Execute in Demo Sandbox</Btn></div>{certificate.stale&&<p className="critical-text">Execution blocked. A new analysis and approval are required.</p>}</div>}
    </section><section className="panel approval-checks"><h3>Execution readiness</h3><Checklist label="Current simulation" done={current}/><Checklist label="Feasible selected plan" done={Boolean(chosen?.feasible)}/><Checklist label="Human review note" done={Boolean(note.trim())}/><Checklist label="Certificate current" done={Boolean(certificate&&!certificate.stale&&certificate.approvalStatus==='approved')}/><Checklist label="Execution committed" done={certificate?.executionStatus==='executed'}/><div className="trust-note">Backend version checks, transaction locking and idempotency prevent unsafe or duplicate execution. Local demo only.</div></section></div>}
   </>}
   {page==='Decision Queue'&&<>
    <PageHeading title="Decision Queue" subtitle="Review and combine human and AI-agent proposals within one scenario." action={<Btn kind="primary" disabled={!queueIds.length} onClick={openQueue}>Analyze Selected Together <ArrowRight size={14}/></Btn>}/>
    <div className="filterbar"><SearchInput value={query} onChange={setQuery}/><select aria-label="Department" value={department} onChange={e=>setDepartment(e.target.value)}><option>All</option>{departments.map(d=><option key={d}>{d}</option>)}</select><select aria-label="Origin" value={originFilter} onChange={e=>setOriginFilter(e.target.value)}><option>All</option><option>Employee</option><option>AI Agent</option></select><select aria-label="Status" value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option>All</option><option value="pending">Pending</option><option value="executed">Executed</option></select><select aria-label="Sort" value={sort} onChange={e=>setSort(e.target.value)}><option>Priority</option><option>Deadline</option></select><span className="result-count">{queueIds.length} selected</span></div>
    <section className="panel table-panel"><div className="table-wrap"><table><thead><tr><th><input type="checkbox" aria-label="Select filtered pending decisions" checked={filteredQueue.some(d=>d.status==='pending')&&filteredQueue.filter(d=>d.status==='pending').every(d=>queueIds.includes(d.id))} onChange={e=>setQueueIds(e.target.checked?[...new Set([...queueIds,...filteredQueue.filter(d=>d.status==='pending').map(d=>d.id)])]:queueIds.filter(id=>!filteredQueue.some(d=>d.id===id)))}/></th><th>ID / SCENARIO</th><th>DEPARTMENT</th><th>ACTION</th><th>RESOURCE</th><th>ORIGIN / SUBMITTED BY</th><th>DEADLINE</th><th>PRIORITY</th><th>STATUS</th><th/></tr></thead><tbody>{filteredQueue.map(d=><tr key={d.id}><td><input type="checkbox" aria-label={`Select ${d.id}`} disabled={d.status!=='pending'} checked={queueIds.includes(d.id)} onChange={e=>setQueueIds(old=>e.target.checked?[...old,d.id]:old.filter(x=>x!==d.id))}/></td><td><button className="table-link" onClick={()=>{setInspector(true);setInspection({title:d.title,subtitle:d.id,fields:Object.entries(d).map(([k,v])=>[k,String(v)])})}}>{d.id}</button><small>{d.scenarioId}</small></td><td>{d.department}</td><td>{d.title}</td><td>{d.resourceId}</td><td>{d.origin}<small>{d.proposedBy}</small></td><td>{date(d.requiredAt)}</td><td><Badge tone={riskTone(d.priority)}>{titleCase(d.priority)}</Badge></td><td><Badge tone={riskTone(d.status)}>{titleCase(d.status)}</Badge></td><td><button className="table-link" onClick={()=>openDecision(d)}>Review <ArrowRight size={12}/></button></td></tr>)}</tbody></table>{!filteredQueue.length&&<Empty text="No matching decisions."/>}</div></section>
   </>}
   {page==='Dependency Explorer'&&<>
    <PageHeading title="Dependency Explorer" subtitle="Trace upstream resources and downstream commitments without writing ERP records."/>
    <div className="workspace-controls"><label className="scenario-select">Scenario <select value={scenarioId} onChange={e=>chooseScenario(e.target.value)}>{scenarios.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label><label className="scenario-select">Entity <select value={entityId||scenario.resources[0]?.id||''} onChange={e=>{setEntityId(e.target.value);setSelectedNode(e.target.value)}}>{scenario.resources.map(r=><option key={r.id} value={r.id}>{r.name} · {r.branchId}</option>)}{scenario.decisions.map(d=><option key={d.id} value={d.id}>{d.title}</option>)}{scenario.commitments.map(c=><option key={c.id} value={c.id}>{c.commitmentType} · {c.customerName}</option>)}</select></label></div>
    <div className="explorer-layout"><section className="panel graph-panel"><PanelTitle title="Operational dependencies" subtitle="Current source relationships; select any node for evidence" action={<GraphFilter value={graphFilter} onChange={setGraphFilter}/>}/>{exploring?<Empty text="Loading dependency records…"/>:explorer?<Graph graph={explorer.graph} filter={graphFilter} selected={selectedNode||entityId} onNode={inspectNode}/>:<Empty text="No graph available."/>}<div className="explorer-footer"><span><i className="legend-dot critical-dot"/> At risk</span><span><i className="legend-dot protected-dot"/> Protected</span><Link href="/decisions" className="text-link">Open scenario <ArrowRight size={13}/></Link></div></section><section className="panel resource-panel"><h3>Resources</h3>{scenario.resources.map(r=><button className="resource-row" key={r.id} onClick={()=>{setEntityId(r.id);setSelectedNode(r.id)}}><Package size={15}/><span><b>{r.name}</b><small>{r.id} · {r.branchId}</small></span><ChevronRight size={13}/></button>)}</section></div>
   </>}
   {page==='Decision History'&&<>
    <PageHeading title="Decision History" subtitle="Persistent, auditable sandbox events and version-bound decision certificates." action={<Btn onClick={csvExport}><Download size={14}/> Export CSV</Btn>}/>
    <div className="filterbar"><SearchInput value={query} onChange={setQuery}/><select value={statusFilter} aria-label="Event type" onChange={e=>setStatusFilter(e.target.value)}><option>All</option>{[...new Set(history.map(h=>h.eventType))].map(t=><option key={t} value={t}>{titleCase(t)}</option>)}</select><input type="date" aria-label="Filter by UTC date" value={historyDate} onChange={e=>setHistoryDate(e.target.value)}/><span className="result-count">{filteredHistory.length} events</span></div><section className="panel table-panel"><div className="table-wrap"><table><thead><tr>{['EVENT','SCENARIO','DESCRIPTION','USER','EXPOSURE BEFORE','EXPOSURE AFTER','SOURCE VERSION','TIMESTAMP','CERTIFICATE'].map(x=><th key={x}>{x}</th>)}</tr></thead><tbody>{filteredHistory.map(h=><tr key={h.id}><td><b>{titleCase(h.eventType)}</b><small>{h.id}</small></td><td>{h.scenarioId}</td><td>{h.description}</td><td>{h.user}</td><td>{typeof h.metadata.exposureBeforeMinor==='number'?money(h.metadata.exposureBeforeMinor):'—'}</td><td>{typeof h.metadata.exposureAfterMinor==='number'?money(h.metadata.exposureAfterMinor):'—'}</td><td>{String(h.metadata.sourceDataVersion??'—')}</td><td>{stamp(h.timestamp)}</td><td>{h.certificateId?<button className="table-link" disabled={Boolean(busy)} onClick={()=>void viewCertificate(h.certificateId!)}><FileText size={13}/> View</button>:'—'}</td></tr>)}</tbody></table>{!filteredHistory.length&&<Empty text="No audit events match the filters."/>}</div></section>
   </>}
   {page==='Integration Center'&&<>
    <PageHeading title="Integration Center" subtitle="Real local MCP protocol connections and AG-UI streaming. All source records are fictional."/>
    <div className="integration-grid">{integrations.map((x,i)=><section key={x.id} className="panel integration-card"><div className="integration-head"><span className="int-icon">{i===0?<Package/>:i===1?<ClipboardCheck/>:i===2?<Boxes/>:<Gauge/>}</span><Badge tone={riskTone(x.status)}>{titleCase(x.status)}</Badge></div><h2>{x.name}</h2><p>{x.description}</p><div className="tool-list"><small>DISCOVERED TOOLS</small>{x.tools.length?x.tools.map(t=><code key={t}>{t}</code>):<span className="muted-copy">{x.id==='finance'?'SQLite adapter, not an MCP server':'Run a test or simulation to discover tools.'}</span>}</div><div className="integration-foot"><span>Latency: {x.lastLatencyMs==null?'Not measured':`${x.lastLatencyMs} ms`}<br/>{stamp(x.lastCheckedAt)}</span>{x.id!=='finance'&&<Btn disabled={Boolean(busy)} onClick={()=>void testConnector(x.id)}>Test Connection</Btn>}</div></section>)}</div>
    <section className="panel agui-panel"><PanelTitle title="AG-UI activity" subtitle="Actual event stream · protocol-shaped run, tool and state events"/><div className="agui-stats"><div><small>RUN ID</small><b title={run?.id}>{run?.id??'No run'}</b></div><div><small>LAST EVENT</small><b>{run?.lastEvent??'Idle'}</b></div><div><small>EVENT COUNT</small><b>{run?.events??0}</b></div><div><small>RUN STATUS / DURATION</small><b>{run?.status??'Idle'}{run?.elapsedMs!=null?` · ${run.elapsedMs} ms`:''}</b></div></div><div className="architecture"><span>Frontend</span><ArrowRight/><span>AG-UI</span><ArrowRight/><span>FastAPI agent</span><ArrowRight/><span>MCP client</span><ArrowRight/><span>MCP servers</span><ArrowRight/><span>SQLite</span></div><ActivityList items={activity}/><Btn kind="primary" onClick={()=>{chooseScenario('SCN-002');router.push('/decisions')}}>Open demo analysis</Btn></section>
   </>}
   </>}
  </main>
  {inspector?<aside className="inspector"><div className="inspector-head"><div><span className="eyebrow">CONTEXT INSPECTOR</span><h2>{inspection?'Record details':'Analysis context'}</h2></div><button className="icon-btn" aria-label="Close inspector" onClick={()=>setInspector(false)}><X size={16}/></button></div>
    {inspection?<div className="inspector-section"><div className="inspector-label">{inspection.subtitle}</div><h3>{inspection.title}</h3><dl className="inspect-fields">{inspection.fields.map(([k,v],i)=><div key={`${k}-${i}`}><dt>{k}</dt><dd>{v}</dd></div>)}</dl>{inspection.evidenceIds?.map(id=>{const e=sourceEvidence.find(x=>x.id===id);return e?<button key={id} className="evidence-row" onClick={()=>inspectEvidence(e)}><FileText size={13}/><span>{e.recordType}</span></button>:null})}<Btn onClick={()=>{setInspection(null);setSelectedNode('')}}>Back to context</Btn></div>:<><div className="inspector-section"><div className="inspector-label">CURRENT WORKSPACE</div><div className="context-card"><Badge tone="info">LOCAL SANDBOX</Badge><b>{scenario?.name??'Connecting'}</b><p>Proposed VitalEdge product extension. Simulations and writes are isolated from real ERP systems.</p><div><span>Data source</span><span>SQLite + MCP</span></div></div></div>{simulation&&<div className="inspector-section"><div className="inspector-label">CURRENT OUTCOME</div><div className={`outcome-card ${simulation.status}`}><span className="outcome-icon"><AlertTriangle size={16}/></span><div><b>{outdated?'Outdated simulation':titleCase(simulation.status)}</b><small>{simulation.resourceConflicts[0]?.explanation??'No resource conflict in this result.'}</small></div></div><dl className="inspect-fields"><div><dt>Revenue at risk</dt><dd>{money(simulation.impactSummary.revenueAtRiskMinor)}</dd></div><div><dt>Customer commitments</dt><dd>{simulation.impactSummary.commitmentsAtRisk} at risk</dd></div></dl></div>}<div className="inspector-section"><div className="inspector-label">AGENT ACTIVITY</div><ActivityList items={activity}/><small>{run?.lastEvent??'Awaiting a simulation'}{run?.elapsedMs!=null?` · ${run.elapsedMs} ms`:''}</small></div><div className="inspector-section"><div className="inspector-label">IMPACTIQ ANALYST</div><p className="muted-copy">Optional LLM explanation of validated results. Cannot approve or execute.</p><div className="analyst-prompts">{['Why is this decision risky?','Which customers are affected?','Why was this plan recommended?'].map(q=><button key={q} disabled={!current||explaining} onClick={()=>void ask(q)}>{q}</button>)}</div><form onSubmit={e=>{e.preventDefault();if(question.trim())void ask(question.trim())}}><label className="sr-only" htmlFor="analyst-question">Question</label><textarea id="analyst-question" placeholder="Ask about this result…" value={question} onChange={e=>setQuestion(e.target.value)} maxLength={1000}/><Btn disabled={!current||explaining||!question.trim()} kind="primary" onClick={()=>void ask(question.trim())}>Explain</Btn>{explaining&&<Btn onClick={()=>{explainAbort.current?.abort();setExplaining(false)}}>Cancel</Btn>}</form>{explanation&&<p className="analyst-answer" role="status">{explanation}</p>}</div></>}
  </aside>:<button className="open-inspector" onClick={()=>setInspector(true)}>Context <ArrowRight size={14}/></button>}
  </div></section>{toast&&<div className="toast" role="status"><CheckCircle2 size={15}/>{toast}<button onClick={()=>setToast('')} aria-label="Dismiss"><X size={13}/></button></div>}{busy&&<div className="busy-status" role="status"><Activity size={14}/> {busy}…</div>}
 </div>
}

function SearchInput({value,onChange}:{value:string;onChange:(v:string)=>void}){return <div className="searchbox"><Search size={15}/><input aria-label="Search records" placeholder="Search records…" value={value} onChange={e=>onChange(e.target.value)}/></div>}
function ActivityList({items}:{items:ActivityItem[]}){return <div className="activity-steps">{items.length?items.map(x=><div key={x.id} className="step-row"><span className={x.status==='completed'?'step-done':x.status==='failed'?'step-failed':'step-running'}>{x.status==='completed'?<Check size={12}/>:x.status==='failed'?<X size={12}/>:<Activity size={12}/>}</span><div><b>{x.label}</b><small>{x.detail??titleCase(x.status)}</small></div></div>):<span className="muted-copy">No events yet.</span>}</div>}
function GraphFilter({value,onChange}:{value:string;onChange:(v:string)=>void}){return <select aria-label="Highlight department" value={value} onChange={e=>onChange(e.target.value)}><option>All</option>{[...departments,'Customer'].map(d=><option key={d}>{d}</option>)}</select>}
function Graph({graph,filter,selected,onNode}:{graph:DependencyGraph;filter:string;selected:string;onNode:(n:DependencyNode)=>void}){
 const order=['Decision','Resource','Operation','Customer commitment','Financial impact'];const grouped=order.map(cat=>graph.nodes.filter(n=>n.category===cat));const width=order.length*220+28,height=Math.max(180,...grouped.map(a=>a.length*90+48));const pts=grouped.flatMap((a,col)=>a.map((n,i)=>({n,x:16+col*220,y:36+i*90})));const lookup=new Map(pts.map(p=>[p.n.id,p]));const highlighted=new Set<string>();if(selected){highlighted.add(selected);let changed=true;while(changed){changed=false;for(const e of graph.edges)if(highlighted.has(e.source)&&!highlighted.has(e.target)){highlighted.add(e.target);changed=true}}}
 const visible=(n:DependencyNode)=>filter==='All'||n.department===filter||highlighted.has(n.id)
 return <div className="graph-scroll"><svg className="impact-graph" viewBox={`0 0 ${width} ${height}`} role="img" aria-label="Operational dependency graph"><defs><marker id="impact-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="#8b9c96"/></marker></defs>{order.map((c,i)=><text key={c} x={16+i*220} y={16} className="graph-category">{c.toUpperCase()}</text>)}{graph.edges.map(e=>{const a=lookup.get(e.source),b=lookup.get(e.target);if(!a||!b)return null;return <path key={e.id} d={`M${a.x+176} ${a.y+30} C${a.x+205} ${a.y+30},${b.x-28} ${b.y+30},${b.x-4} ${b.y+30}`} fill="none" stroke={e.severity==='critical'||e.severity==='high'?'#b86d72':'#9eafa9'} strokeWidth={highlighted.has(e.source)&&highlighted.has(e.target)?2.6:1.4} opacity={visible(a.n)&&visible(b.n)?1:.18} markerEnd="url(#impact-arrow)"/>})}{pts.map(({n,x,y})=><g key={n.id} className="graph-node" tabIndex={0} role="button" aria-label={`${n.category}: ${n.label}`} opacity={visible(n)?1:.35} onClick={()=>onNode(n)} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();onNode(n)}}}><title>{n.label}: {n.description}</title><rect x={x} y={y} width="176" height="62" rx="5" fill={n.severity==='critical'?'#fff0f0':n.severity==='high'?'#fff7e9':'#f6faf8'} stroke={n.id===selected?'#087f7a':n.severity==='critical'?'#e7b9bc':n.severity==='high'?'#ead5b2':'#d6e3dd'} strokeWidth={n.id===selected?2:1}/><circle cx={x+10} cy={y+12} r="3" fill={n.severity==='critical'?'#b42332':n.severity==='high'?'#b7791f':'#247a55'}/><text x={x+18} y={y+15} className="graph-category">{n.department.toUpperCase()}</text><text x={x+8} y={y+34} className="graph-label">{n.label.length>27?n.label.slice(0,25)+'…':n.label}</text><text x={x+8} y={y+51} className="graph-desc">{n.entityId}</text></g>)}</svg></div>
}
function ImpactPanel({result,scenario,current,commitmentFilter,onCommitmentFilter,graphFilter,setGraphFilter,selectedNode,onNode,onEvidence,onAlternatives}:{result:SimulationResult;scenario:Scenario;current:boolean;commitmentFilter:string;onCommitmentFilter:(v:string)=>void;graphFilter:string;setGraphFilter:(v:string)=>void;selectedNode:string;onNode:(n:DependencyNode)=>void;onEvidence:(e:EvidenceRecord)=>void;onAlternatives:()=>void}){
 const conflicts=result.resourceConflicts;const original=result.alternatives.find(p=>p.id==='PLAN-BASE');const filtered=result.affectedCommitments.filter(c=>commitmentFilter==='All'||c.simulatedStatus===commitmentFilter)
 return <><div className={`outcome-banner ${!current?'warning':result.status}`}><span className="banner-icon"><AlertTriangle size={18}/></span><div><b>{!current?'Outdated simulation':result.status==='critical'?'Combined decision conflict detected':result.status==='warning'?'Business constraints require review':'Selected decisions satisfy modeled constraints'}</b><p>{conflicts[0]?.explanation??original?.recommendationReason??'No resource conflict.'}</p></div><div className="banner-side"><small>REVENUE AT RISK · ESTIMATE</small><b>{money(result.impactSummary.revenueAtRiskMinor)}</b><small>Not a confirmed financial loss</small></div></div>
 <div className="impact-metrics"><div><small>CONFLICTS</small><b>{result.impactSummary.conflictCount}</b></div><div><small>AT-RISK COMMITMENTS</small><b>{result.impactSummary.commitmentsAtRisk}</b></div><div><small>PROTECTED</small><b>{result.impactSummary.protectedCommitments}</b></div><div><small>ADDITIONAL COST</small><b>{money(result.impactSummary.additionalCostMinor)}</b></div><div><small>DELAY ESTIMATE</small><b>{result.impactSummary.estimatedDelayHours??'Unknown'} <em>hrs</em></b></div></div>
 <section className="panel"><PanelTitle title="Individual vs. combined feasibility" subtitle="Each decision is evaluated on its own before shared resource constraints are applied."/><div className="table-wrap"><table><thead><tr><th>DECISION</th><th>REQUIRED</th><th>UNALLOCATED / ASSET</th><th>INDIVIDUAL RESULT</th></tr></thead><tbody>{result.individualEvaluations.map(e=><tr key={e.decisionId}><td><b>{e.decisionId}</b></td><td>{e.required}</td><td>{e.available}</td><td><Badge tone={e.feasible?'success':'critical'}>{e.feasible?'Feasible':'Conflict'}</Badge></td></tr>)}</tbody></table></div>{conflicts.map(c=><div className="resource-conflict" key={c.id}><b>{c.resourceName} · {c.branchId}</b><div className="impact-metrics compact"><div><small>AVAILABLE</small><b>{c.availableQuantity}</b></div><div><small>COMBINED DEMAND</small><b>{c.requiredQuantity}</b></div><div className="deficit"><small>DEFICIT / CONFLICT</small><b>{c.deficitQuantity}</b></div></div><p>{c.explanation}</p></div>)}</section>
 <section className="panel graph-panel"><PanelTitle title="Cascading dependencies" subtitle="Follow decision → resource → operation → customer → exposure." action={<GraphFilter value={graphFilter} onChange={setGraphFilter}/>}/><Graph graph={result.graph} filter={graphFilter} selected={selectedNode} onNode={onNode}/></section>
 <section className="panel commitments-panel"><PanelTitle title="Customer commitment impact" subtitle="Unselected or unmodeled commitments remain unknown." action={<select value={commitmentFilter} aria-label="Commitment status" onChange={e=>onCommitmentFilter(e.target.value)}><option>All</option><option value="at risk">At risk</option><option value="protected">Protected</option><option value="unknown">Unknown</option></select>}/><div className="table-wrap"><table><thead><tr><th>COMMITMENT / CUSTOMER</th><th>TYPE</th><th>DUE</th><th>BASELINE</th><th>SIMULATED</th><th>DELAY</th><th>EXPOSURE</th><th>REASON</th></tr></thead><tbody>{filtered.map(x=>{const c=scenario.commitments.find(c=>c.id===x.commitmentId);return <tr key={x.commitmentId}><td><b>{x.commitmentId}</b><small>{c?.customerName}</small></td><td>{c?.commitmentType}</td><td>{c?date(c.dueAt):'Unknown'}</td><td>{x.baselineStatus}</td><td><Badge tone={riskTone(x.simulatedStatus)}>{x.simulatedStatus}</Badge></td><td>{x.estimatedDelayHours==null?'Unknown':`${x.estimatedDelayHours} hrs`}</td><td>{x.simulatedStatus==='unknown'?'Unknown':money(x.revenueAtRiskMinor)}</td><td>{x.reason}</td></tr>})}</tbody></table>{!filtered.length&&<Empty text="No matching commitments."/>}</div></section>
 <section className="panel evidence-panel"><PanelTitle title="Supporting evidence" subtitle="Actual retrieved records from fictional MCP/SQLite data sources."/><div className="evidence-grid">{result.evidence.map(e=><button className="evidence-card" key={e.id} onClick={()=>onEvidence(e)}><span className="evidence-check"><Check size={12}/></span><div><b>{e.recordType}</b><small>{e.sourceSystem} · {e.recordId}</small></div></button>)}</div></section><div className="decision-footer"><span><b>{result.id}</b><small>Revision {result.scenarioRevision} · {result.sourceDataVersion}</small></span><Btn kind="primary" onClick={onAlternatives}>Compare alternatives <ArrowRight size={14}/></Btn></div></>
}
function PlanCard({plan,selected,recommended,count,disabled,onSelect}:{plan:AlternativePlan;selected:boolean;recommended:boolean;count:number;disabled:boolean;onSelect:()=>void}){return <article className={`alternative-card ${selected?'chosen':''} ${recommended?'recommended':''}`}><div className="alt-top"><Badge tone={plan.feasible?'success':'critical'}>{plan.feasible?'Feasible':'Constraint violation'}</Badge>{recommended&&<span className="recommend-label">RECOMMENDED</span>}{plan.id==='PLAN-BASE'&&<span className="recommend-label">BASELINE</span>}</div><h3>{plan.title}</h3><p>{plan.description}</p><div className="alt-metrics"><div><small>Revenue at risk</small><b>{money(plan.impactSummary.revenueAtRiskMinor)}</b></div><div><small>Additional cost</small><b>{money(plan.impactSummary.additionalCostMinor)}</b></div><div><small>Protected commitments</small><b>{plan.impactSummary.protectedCommitments} / {count}</b></div><div><small>Conflicts</small><b>{plan.impactSummary.conflictCount}</b></div><div><small>Expected delay</small><b>{plan.impactSummary.estimatedDelayHours??'Unknown'} hrs</b></div></div><ul>{plan.actions.map((a,i)=><li key={i}>{a}</li>)}</ul><p className={plan.feasible?'muted-copy':'critical-text'}>{plan.recommendationReason}</p><button className={`btn ${selected?'primary':'secondary'} full-btn`} disabled={disabled} onClick={onSelect}>{selected?'Selected plan':'Select for review'}</button></article>}
